    SET IDENTITY_INSERT dbo.[CustomerAddresses] OFF;

    -- Vehicles: 100 kayıt
    SET IDENTITY_INSERT dbo.[Vehicles] ON;
    SET IDENTITY_INSERT dbo.[Vehicles] OFF;

    -- Reservations: 80 kayıt
    SET IDENTITY_INSERT dbo.[Reservations] ON;
