GO

-- Aktarılan kayıt sayıları
SELECT 'VehicleBrands' AS TableName, COUNT(*) AS RecordCount FROM dbo.VehicleBrands
UNION ALL SELECT 'VehicleModels', COUNT(*) FROM dbo.VehicleModels
UNION ALL SELECT 'VehicleCategories', COUNT(*) FROM dbo.VehicleCategories
UNION ALL SELECT 'Vehicles', COUNT(*) FROM dbo.Vehicles
UNION ALL SELECT 'Customers', COUNT(*) FROM dbo.Customers
UNION ALL SELECT 'CustomerAddresses', COUNT(*) FROM dbo.CustomerAddresses
UNION ALL SELECT 'Reservations', COUNT(*) FROM dbo.Reservations
UNION ALL SELECT 'RentalContracts', COUNT(*) FROM dbo.RentalContracts
UNION ALL SELECT 'RentalContractDrivers', COUNT(*) FROM dbo.RentalContractDrivers
UNION ALL SELECT 'MaintenanceTypes', COUNT(*) FROM dbo.MaintenanceTypes
UNION ALL SELECT 'MaintenanceRecords', COUNT(*) FROM dbo.MaintenanceRecords
UNION ALL SELECT 'TrafficFines', COUNT(*) FROM dbo.TrafficFines
UNION ALL SELECT 'FinePayments', COUNT(*) FROM dbo.FinePayments
UNION ALL SELECT 'VehicleExpenses', COUNT(*) FROM dbo.VehicleExpenses
UNION ALL SELECT 'Users', COUNT(*) FROM dbo.Users
UNION ALL SELECT 'Locations', COUNT(*) FROM dbo.Locations;
GO
